
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_scanl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_scanl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.885392040126328e+00, -4.786555800935257e+00, -4.648029164942637e+00, -4.456065958173433e+00, -4.194347411014212e+00, -3.845725674653452e+00, -3.396116624657940e+00, -2.835574692360704e+00, -2.193240034305922e+00, -1.507521971422254e+00, -8.604839801732641e-01, -6.503906384423775e-01, -6.624222429359177e-01, -5.304426282800493e-01, -3.584995670418795e-01, -1.909837600860129e-01, -7.518958100279025e-02, -2.079447304528774e-02, -2.952308219004400e-03, -1.408911732767009e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


